import Stripe from 'stripe';

const UNKNOWN_ERROR_CODE = 'unknown_error';

function paymentErrorMessage(error: unknown): string {
  if (error instanceof Error) {
    return error.message;
  }
  return String(error);
}

function paymentErrorCode(error: unknown): string {
  if (typeof error !== 'object' || error === null) {
    return UNKNOWN_ERROR_CODE;
  }
  const record = error as Record<string, unknown>;
  const code = record.code;
  if (typeof code === 'string' && code.length > 0) {
    return code;
  }
  const typ = record.type;
  if (typeof typ === 'string' && typ.length > 0) {
    return typ;
  }
  return UNKNOWN_ERROR_CODE;
}

/**
 * Payment gateway interface — contract for payment providers.
 */
export interface PaymentGateway {
  charge(params: ChargeParams): Promise<PaymentResult>;
  refund(params: RefundParams): Promise<PaymentResult>;
}

/**
 * Charge parameters (amount in smallest currency unit, e.g. cents).
 */
export interface ChargeParams {
  amount: number;
  currency: string;
  source?: string | null;
  metadata?: Record<string, string>;
}

/**
 * Refund parameters.
 */
export interface RefundParams {
  transactionId: string;
  amount: number;
}

/**
 * Result of a charge or refund operation.
 */
export interface PaymentResult {
  success: boolean;
  transactionId?: string;
  refundTransactionId?: string;
  response?: string;
  error?: string;
  errorCode?: string;
}

/**
 * Stripe implementation of {@link PaymentGateway} (async Node SDK).
 */
export class StripePaymentGateway implements PaymentGateway {
  private stripe: Stripe | null = null;

  private readonly testMode: boolean;

  constructor() {
    this.testMode = process.env.PAYMENT_TEST_MODE?.toLowerCase() === 'true';
    if (this.testMode) {
      console.log('payment_gateway_initialized provider=stripe mode=test');
    } else {
      console.log('payment_gateway_initialized provider=stripe mode=production');
    }
  }

  private ensureConfigured(): void {
    if (this.stripe !== null) {
      return;
    }
    const key = process.env.STRIPE_SECRET_KEY;
    if (!key || key.trim() === '') {
      throw new Error(
        'STRIPE_SECRET_KEY environment variable is required for production payment processing. ' +
          'Set PAYMENT_TEST_MODE=true for testing without Stripe credentials.',
      );
    }
    this.stripe = new Stripe(key, { apiVersion: '2023-10-16' });
  }

  private validateChargeParams(params: ChargeParams): PaymentResult | null {
    if (params.amount === undefined || params.amount === null || params.amount <= 0) {
      return {
        success: false,
        error: 'Amount must be a positive number',
        errorCode: 'invalid_amount',
      };
    }

    const cur = params.currency?.trim() ?? '';
    if (cur.length !== 3) {
      return {
        success: false,
        error: "Currency must be a 3-letter ISO code (e.g., 'usd', 'eur')",
        errorCode: 'invalid_currency',
      };
    }

    return null;
  }

  private validateRefundParams(params: RefundParams): PaymentResult | null {
    const tx = params.transactionId?.trim() ?? '';
    if (tx === '') {
      return {
        success: false,
        error: 'Transaction ID must be a non-empty string',
        errorCode: 'invalid_transaction_id',
      };
    }

    if (params.amount === undefined || params.amount === null || params.amount <= 0) {
      return {
        success: false,
        error: 'Refund amount must be a positive number',
        errorCode: 'invalid_amount',
      };
    }

    return null;
  }

  async charge(params: ChargeParams): Promise<PaymentResult> {
    const validationError = this.validateChargeParams(params);
    if (validationError !== null) {
      return validationError;
    }

    if (this.testMode) {
      return this.mockCharge(params);
    }

    this.ensureConfigured();
    try {
      const charge = await this.stripe!.charges.create({
        amount: params.amount,
        currency: params.currency.trim().toLowerCase(),
        ...(params.source !== undefined && params.source !== null && params.source !== ''
          ? { source: params.source }
          : {}),
        ...(params.metadata !== undefined ? { metadata: params.metadata } : {}),
      });
      console.log(`payment_charge_success charge_id=${charge.id}`);
      return {
        success: true,
        transactionId: charge.id,
        response: JSON.stringify(charge),
      };
    } catch (error: unknown) {
      const errorCode = paymentErrorCode(error);
      const message = paymentErrorMessage(error);
      console.error(`payment_charge_failed error=${message} code=${errorCode}`);
      return {
        success: false,
        error: message,
        errorCode,
      };
    }
  }

  async refund(params: RefundParams): Promise<PaymentResult> {
    const validationError = this.validateRefundParams(params);
    if (validationError !== null) {
      return validationError;
    }

    if (this.testMode) {
      return this.mockRefund(params);
    }

    this.ensureConfigured();
    try {
      const refund = await this.stripe!.refunds.create({
        charge: params.transactionId.trim(),
        amount: params.amount,
      });
      console.log(
        `payment_refund_success refund_id=${refund.id} charge_id=${params.transactionId.trim()}`,
      );
      return {
        success: true,
        transactionId: params.transactionId.trim(),
        refundTransactionId: refund.id,
        response: JSON.stringify(refund),
      };
    } catch (error: unknown) {
      const errorCode = paymentErrorCode(error);
      const message = paymentErrorMessage(error);
      console.error(`payment_refund_failed error=${message} code=${errorCode}`);
      return {
        success: false,
        error: message,
        errorCode,
      };
    }
  }

  private mockCharge(params: ChargeParams): PaymentResult {
    const txId = `test_ch_${Date.now()}_${Math.floor(Math.random() * 10000)}`;
    console.log(
      `payment_charge_test_mode amount=${params.amount} currency=${params.currency.trim()} tx_id=${txId}`,
    );
    return {
      success: true,
      transactionId: txId,
      response: JSON.stringify({
        id: txId,
        amount: params.amount,
        currency: params.currency.trim(),
        status: 'succeeded',
        test_mode: true,
      }),
    };
  }

  private mockRefund(params: RefundParams): PaymentResult {
    const refundId = `test_refund_${Date.now()}_${Math.floor(Math.random() * 10000)}`;
    const chargeId = params.transactionId.trim();
    console.log(
      `payment_refund_test_mode tx_id=${chargeId} amount=${params.amount} refund_id=${refundId}`,
    );
    return {
      success: true,
      transactionId: chargeId,
      refundTransactionId: refundId,
      response: JSON.stringify({
        id: refundId,
        charge: chargeId,
        amount: params.amount,
        status: 'succeeded',
        test_mode: true,
      }),
    };
  }
}

export const stripeGateway = new StripePaymentGateway();
